const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.0",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/public\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ===== PLATFORM AUTHORITY =====\n\nenum LegacyPlatformRole {\n  super_admin\n}\n\nenum Role {\n  super_admin\n  school_admin\n  principal\n  teacher\n  bursar\n  student\n  guardian\n}\n\nenum Persona {\n  STAFF\n  STUDENT\n  GUARDIAN\n}\n\nenum MemberStatus {\n  active\n  suspended\n  removed\n}\n\nenum PlatformRoleKind {\n  LOCKED\n  CUSTOM\n}\n\nenum PermissionScope {\n  ALL\n  BRANCH\n  ASSIGNED\n  OWN\n}\n\nenum PermissionRealm {\n  PLATFORM\n  SCHOOL\n}\n\nenum SchoolCategory {\n  primary\n  secondary\n  primary_secondary\n}\n\nenum SchoolOwnership {\n  private\n  public\n  mission\n  international\n}\n\nenum SchoolStatus {\n  pending\n  active\n  suspended\n  deactivated\n}\n\nenum VerificationStatus {\n  unverified\n  under_review\n  verified\n  rejected\n}\n\nenum IdDocumentType {\n  nin\n  voters_card\n  drivers_license\n  international_passport\n  other\n}\n\nenum DocumentType {\n  cac_certificate\n  proprietor_id\n  waec_approval\n  ministry_approval\n  other\n}\n\nenum DocumentStatus {\n  pending\n  under_review\n  approved\n  rejected\n}\n\nenum OtpType {\n  email_verification\n  password_reset\n  two_factor\n}\n\nenum SubscriptionStatus {\n  trialing\n  active\n  past_due\n  suspended\n  cancelled\n  expired\n}\n\nenum BillingCycle {\n  monthly\n  yearly\n}\n\nenum DiscountType {\n  percentage\n  fixed_amount\n}\n\nenum PaymentStatus {\n  pending\n  success\n  failed\n  refunded\n}\n\nenum BillingInvoiceStatus {\n  open\n  paid\n  void\n  uncollectible\n}\n\nenum BillingInvoiceReason {\n  upgrade\n  renewal\n  adjustment\n}\n\nenum BillingItemKind {\n  plan\n  setup_fee\n  proration_credit\n  discount\n  adjustment\n}\n\nenum PaymentAttemptStatus {\n  pending\n  success\n  failed\n  abandoned\n}\n\nenum PaymentAttemptMethod {\n  checkout\n  saved_card\n  manual\n}\n\nenum WebhookEventStatus {\n  received\n  processed\n  ignored\n  failed\n}\n\nenum FeatureKind {\n  BOOLEAN\n  LIMIT\n  QUOTA\n  ENUM\n}\n\nenum Enforcement {\n  BLOCK\n  WARN\n}\n\nenum DefinitionOrigin {\n  CODE\n  PLATFORM\n}\n\nenum SettingType {\n  BOOLEAN\n  INTEGER\n  DECIMAL\n  STRING\n  ENUM\n  TIME\n  STRING_LIST\n  INTEGER_LIST\n  ENTITY_REF\n}\n\nenum AutomationTrigger {\n  EVENT\n  SCHEDULE\n  OFFSET_BEFORE\n  OFFSET_AFTER\n}\n\nenum TemplateCategory {\n  AUTH\n  BILLING\n  SYSTEM\n  FEES\n  ACADEMIC\n  ATTENDANCE\n  GENERAL\n}\n\nenum ActorType {\n  user\n  system\n  super_admin\n  webhook\n}\n\nenum PlatformNotificationType {\n  welcome\n  feature_announcement\n  subscription_expiry\n  subscription_renewed\n  subscription_failed\n  account_suspended\n  account_verified\n  account_rejected\n  system_alert\n}\n\nenum NotificationChannel {\n  IN_APP\n  EMAIL\n  SMS\n}\n\nenum NotificationState {\n  DRAFT\n  QUEUED\n  PROCESSING\n  COMPLETED\n  CANCELLED\n}\n\nenum DeliveryStatus {\n  PENDING\n  QUEUED\n  SENT\n  DELIVERED\n  READ\n  FAILED\n  CANCELLED\n}\n\nenum FeedbackType {\n  bug\n  suggestion\n  complaint\n  praise\n}\n\nenum FeedbackStatus {\n  open\n  reviewed\n  resolved\n}\n\n// ===== SCHOOL =====\n\nmodel School {\n  // Primary identifier\n  id   String @id @default(uuid())\n  name String\n\n  // Domain and contact information\n  subdomain              String    @unique\n  customDomain           String?\n  customDomainVerifiedAt DateTime?\n  email                  String    @unique\n  phone                  String?\n  website                String?\n  logoUrl                String?\n\n  // Address information\n  address  String?\n  city     String?\n  state    String?\n  country  String  @default(\"Nigeria\")\n  timezone String  @default(\"Africa/Lagos\")\n\n  // School classification\n  schoolCategory  SchoolCategory  @default(primary)\n  schoolOwnership SchoolOwnership @default(private)\n\n  // Status and verification\n  status             SchoolStatus       @default(pending)\n  verificationStatus VerificationStatus @default(unverified)\n  verificationNote   String?\n  verifiedAt         DateTime?\n  verifiedById       String?\n  activatedAt        DateTime?\n  isActive           Boolean            @default(false)\n\n  // Suspension and deletion\n  suspendedAt      DateTime?\n  suspensionReason String?\n  deletedAt        DateTime?\n\n  // Multi-tenant schema provisioning\n  schemaName          String?   @unique\n  schemaProvisionedAt DateTime?\n\n  // Paystack settlement information\n  paystackSubaccountCode  String?\n  paystackSubaccountId    String?\n  settlementBankCode      String?\n  settlementAccountNumber String?\n  settlementAccountName   String?\n  settlementAccountLast4  String?\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relationships\n  users                          User[]\n  userSchools                    UserSchool[]\n  subscriptions                  Subscription[]\n  documents                      SchoolDocument[]\n  auditLogs                      AuditLog[]\n  platformNotificationRecipients PlatformNotificationRecipient[]\n  entitlementOverrides           SchoolEntitlementOverride[]\n  feedback                       Feedback[]\n  subscriptionInvoices           SubscriptionInvoice[]\n  paymentMethods                 PaymentMethod[]\n\n  // Indexes\n  @@index([status])\n  @@index([status, activatedAt])\n  @@index([deletedAt])\n}\n\nmodel SchoolDocument {\n  id                    String          @id @default(uuid())\n  schoolId              String\n  type                  DocumentType\n  idDocumentType        IdDocumentType?\n  idNumber              String?\n  proprietorFullName    String?\n  proprietorDateOfBirth DateTime?\n  fileUrl               String\n  status                DocumentStatus  @default(pending)\n  rejectionReason       String?\n  verifiedAt            DateTime?\n  verifiedById          String?\n  apiVerified           Boolean         @default(false)\n  apiResponse           Json?\n  createdAt             DateTime        @default(now())\n  updatedAt             DateTime        @updatedAt\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  @@index([schoolId])\n}\n\n// ===== AUTH / IDENTITY MODULE =====\n\nmodel User {\n  id String @id @default(uuid())\n\n  // Legacy tenant context retained until the final migration stage.\n  schoolId String?\n\n  email        String @unique\n  passwordHash String\n\n  // Legacy authorization fields retained during migration.\n  role         Role\n  platformRole LegacyPlatformRole?\n\n  firstName String?\n  lastName  String?\n  phone     String?\n  photoUrl  String?\n\n  isActive           Boolean   @default(true)\n  isEmailVerified    Boolean   @default(false)\n  emailVerifiedAt    DateTime?\n  lastLoginAt        DateTime?\n  lastLoginIp        String?\n  failedLoginCount   Int       @default(0)\n  lockedUntil        DateTime?\n  passwordChangedAt  DateTime?\n  mustChangePassword Boolean   @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  school         School?         @relation(fields: [schoolId], references: [id])\n  platformMember PlatformMember?\n  schools        UserSchool[]\n  refreshTokens  RefreshToken[]\n  otps           Otp[]\n  invitesSent    Invite[]        @relation(\"InviteSender\")\n  feedback       Feedback[]\n\n  @@index([schoolId])\n  @@index([platformRole])\n}\n\nmodel UserSchool {\n  userId    String\n  schoolId  String\n  createdAt DateTime @default(now())\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  school School @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n\n  @@id([userId, schoolId])\n  @@index([schoolId])\n}\n\nmodel Otp {\n  id String @id @default(uuid())\n\n  userId String\n  code   String\n  type   OtpType\n\n  expiresAt DateTime\n  usedAt    DateTime?\n  attempts  Int       @default(0)\n\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, type])\n  @@index([expiresAt])\n}\n\nmodel RefreshToken {\n  id             String    @id @default(uuid())\n  userId         String\n  token          String    @unique // HMAC of the JWT\n  familyId       String\n  schoolId       String?\n  membershipId   String?\n  impersonatorId String?\n  userAgent      String?\n  ipAddress      String?\n  lastUsedAt     DateTime?\n  revokedAt      DateTime?\n  replacedById   String?\n  expiresAt      DateTime\n  createdAt      DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([familyId])\n}\n\nmodel Invite {\n  id String @id @default(uuid())\n\n  email String\n\n  // Legacy role retained until the final migration stage.\n  role Role\n\n  persona         Persona   @default(STAFF)\n  personaEntityId String?\n  roleId          String?\n  roleKey         String?\n  token           String    @unique\n  schoolId        String\n  sentById        String\n  accepted        Boolean   @default(false)\n  acceptedAt      DateTime?\n  revokedAt       DateTime?\n  expiresAt       DateTime\n  createdAt       DateTime  @default(now())\n\n  sentBy User @relation(\"InviteSender\", fields: [sentById], references: [id])\n\n  @@index([schoolId, email])\n  @@index([roleId])\n  @@index([roleKey])\n  @@index([expiresAt])\n}\n\n// ===== BILLING / SUBSCRIPTION MODULE =====\n\nmodel Plan {\n  id          String  @id @default(uuid())\n  name        String  @unique\n  systemKey   String? @unique\n  description String?\n\n  // Legacy fields retained until final cleanup\n  studentLimit Int  @default(0)\n  staffLimit   Int  @default(0)\n  features     Json @default(\"{}\")\n\n  // Pricing\n  monthlyPriceKobo Int @default(0)\n  yearlyPriceKobo  Int @default(0)\n  setupFeeKobo     Int @default(0)\n\n  // Availability and plan type\n  isPublic Boolean @default(true)\n  isActive Boolean @default(true)\n  isCustom Boolean @default(false)\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relationships\n  subscriptions Subscription[]\n  entitlements  PlanEntitlement[]\n  invoices      SubscriptionInvoice[]\n}\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  schoolId            String\n  planId              String\n  status              SubscriptionStatus @default(active)\n  billingCycle        BillingCycle       @default(monthly)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  trialEndsAt         DateTime?\n  cancelAtPeriodEnd   Boolean            @default(false)\n  cancelledAt         DateTime?\n  couponId            String?\n  discountedPriceKobo Int?\n  autoRenew           Boolean            @default(false)\n\n  // Legacy Paystack and billing fields retained during migration\n  paystackAuthorizationCode String?\n  paystackCustomerCode      String?\n  paystackSubscriptionCode  String?\n  scheduledDowngradePlanId  String?\n  setupFeePaid              Boolean   @default(false)\n  setupFeePaidAt            DateTime?\n  nextBillingDate           DateTime?\n  lastBillingAttemptAt      DateTime?\n  failedBillingCount        Int       @default(0)\n\n  // New billing-engine fields\n  paymentMethodId  String?\n  billingAnchorDay Int     @default(1)\n  lapsedPlanId     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  school         School           @relation(fields: [schoolId], references: [id])\n  plan           Plan             @relation(fields: [planId], references: [id])\n  coupon         Coupon?          @relation(fields: [couponId], references: [id])\n  billingHistory BillingHistory[]\n\n  invoices SubscriptionInvoice[]\n\n  @@index([schoolId, status])\n  @@index([planId])\n  @@index([currentPeriodEnd])\n}\n\nmodel Coupon {\n  id String @id @default(uuid())\n\n  code        String  @unique\n  description String?\n\n  discountType  DiscountType\n  discountValue Int\n\n  maxUses   Int?\n  usedCount Int  @default(0)\n\n  validFrom  DateTime\n  validUntil DateTime?\n\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  subscriptions Subscription[]\n}\n\nmodel BillingHistory {\n  id String @id @default(uuid())\n\n  subscriptionId String\n\n  amountKobo Int\n  status     PaymentStatus @default(pending)\n\n  billingCycle      BillingCycle\n  paystackReference String?\n\n  paidAt        DateTime?\n  failureReason String?\n\n  createdAt DateTime @default(now())\n\n  subscription Subscription @relation(fields: [subscriptionId], references: [id])\n\n  @@index([subscriptionId, createdAt])\n  @@index([status])\n}\n\n// ===== BILLING ENGINE =====\n\n// One invoice per charge.\n// Subscription state follows invoice state, never the other way round.\nmodel SubscriptionInvoice {\n  id                String               @id @default(uuid())\n  number            String               @unique\n  idempotencyKey    String?              @unique\n  subscriptionId    String\n  schoolId          String\n  planId            String\n  billingCycle      BillingCycle\n  reason            BillingInvoiceReason\n  status            BillingInvoiceStatus @default(open)\n  periodStart       DateTime\n  periodEnd         DateTime\n  subtotalKobo      Int\n  discountKobo      Int                  @default(0)\n  totalKobo         Int\n  amountPaidKobo    Int                  @default(0)\n  couponId          String?\n  dueDate           DateTime\n  issuedAt          DateTime             @default(now())\n  paidAt            DateTime?\n  voidedAt          DateTime?\n  attemptCount      Int                  @default(0)\n  nextAttemptAt     DateTime?\n  lastFailureReason String?\n  note              String?\n  createdById       String?\n  createdAt         DateTime             @default(now())\n  updatedAt         DateTime             @updatedAt\n\n  subscription Subscription @relation(fields: [subscriptionId], references: [id])\n  school       School       @relation(fields: [schoolId], references: [id])\n  plan         Plan         @relation(fields: [planId], references: [id])\n\n  items    SubscriptionInvoiceItem[]\n  attempts PaymentAttempt[]\n\n  @@index([schoolId, createdAt])\n  @@index([subscriptionId, status])\n  @@index([status, dueDate])\n  @@index([status, nextAttemptAt])\n}\n\nmodel SubscriptionInvoiceItem {\n  id          String          @id @default(uuid())\n  invoiceId   String\n  kind        BillingItemKind\n  description String\n  amountKobo  Int\n  createdAt   DateTime        @default(now())\n\n  invoice SubscriptionInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n}\n\nmodel PaymentAttempt {\n  id              String               @id @default(uuid())\n  invoiceId       String\n  reference       String               @unique\n  amountKobo      Int\n  status          PaymentAttemptStatus @default(pending)\n  method          PaymentAttemptMethod\n  paymentMethodId String?\n  providerStatus  String?\n  failureReason   String?\n  createdAt       DateTime             @default(now())\n  completedAt     DateTime?\n\n  invoice SubscriptionInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n  @@index([status, createdAt])\n}\n\n// Saved payment methods.\n// authorizationCode must be encrypted by the application.\nmodel PaymentMethod {\n  id                String    @id @default(uuid())\n  schoolId          String\n  provider          String    @default(\"paystack\")\n  authorizationCode String\n  signature         String?\n  brand             String?\n  last4             String?\n  expMonth          Int?\n  expYear           Int?\n  bank              String?\n  checkoutEmail     String\n  isDefault         Boolean   @default(true)\n  createdAt         DateTime  @default(now())\n  removedAt         DateTime?\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  @@unique([schoolId, signature])\n  @@index([schoolId, removedAt])\n}\n\n// Idempotent provider webhook-event log.\nmodel WebhookEvent {\n  id          String             @id @default(uuid())\n  provider    String\n  eventKey    String\n  eventType   String\n  reference   String?\n  status      WebhookEventStatus @default(received)\n  error       String?\n  receivedAt  DateTime           @default(now())\n  processedAt DateTime?\n\n  @@unique([provider, eventKey])\n  @@index([status, receivedAt])\n}\n\n// Prevents duplicate billing reminders.\nmodel BillingNotice {\n  subscriptionId String\n  periodEnd      DateTime\n  key            String\n  sentAt         DateTime @default(now())\n\n  @@id([subscriptionId, periodEnd, key])\n}\n\n// Invoice-number sequence counters.\nmodel PlatformSequence {\n  key       String\n  period    String   @default(\"\")\n  nextValue Int      @default(1)\n  updatedAt DateTime @updatedAt\n\n  @@id([key, period])\n}\n\n// ===== PLATFORM RBAC =====\n\nmodel PlatformRole {\n  id          String           @id @default(uuid())\n  name        String           @unique\n  description String?\n  systemKey   String?          @unique\n  kind        PlatformRoleKind\n  grantsAll   Boolean          @default(false)\n  isActive    Boolean          @default(true)\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  permissions PlatformRolePermission[]\n  members     PlatformMemberRole[]\n}\n\nmodel PlatformRolePermission {\n  roleId        String\n  permissionKey String\n\n  role       PlatformRole         @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission PermissionDefinition @relation(fields: [permissionKey], references: [key])\n\n  @@id([roleId, permissionKey])\n  @@index([permissionKey])\n}\n\nmodel PlatformMember {\n  id        String       @id @default(uuid())\n  userId    String       @unique\n  status    MemberStatus @default(active)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  user  User                 @relation(fields: [userId], references: [id], onDelete: Cascade)\n  roles PlatformMemberRole[]\n}\n\nmodel PlatformMemberRole {\n  memberId     String\n  roleId       String\n  assignedAt   DateTime @default(now())\n  assignedById String?\n\n  member PlatformMember @relation(fields: [memberId], references: [id], onDelete: Cascade)\n  role   PlatformRole   @relation(fields: [roleId], references: [id])\n\n  @@id([memberId, roleId])\n  @@index([roleId])\n}\n\nmodel PermissionDefinition {\n  key                 String            @id\n  realm               PermissionRealm\n  module              String\n  scopes              PermissionScope[]\n  personas            Persona[]\n  requiresFeature     String?\n  introducedInVersion Int\n  label               String\n  description         String?\n  isSensitive         Boolean           @default(false)\n  isDeprecated        Boolean           @default(false)\n  sortOrder           Int               @default(0)\n  createdAt           DateTime          @default(now())\n  updatedAt           DateTime          @updatedAt\n\n  templatePermissions     RoleTemplatePermission[]\n  platformRolePermissions PlatformRolePermission[]\n\n  @@index([realm, module])\n  @@index([isDeprecated])\n}\n\nmodel RoleTemplate {\n  id                String   @id @default(uuid())\n  key               String   @unique\n  name              String\n  description       String?\n  persona           Persona  @default(STAFF)\n  isLocked          Boolean  @default(false)\n  grantsAll         Boolean  @default(false)\n  autoProvision     Boolean  @default(true)\n  defaultForPersona Persona? @unique\n  version           Int      @default(1)\n  isActive          Boolean  @default(true)\n  sortOrder         Int      @default(0)\n  updatedById       String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  permissions RoleTemplatePermission[]\n}\n\nmodel RoleTemplatePermission {\n  templateId    String\n  permissionKey String\n  scope         PermissionScope @default(ALL)\n\n  template   RoleTemplate         @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  permission PermissionDefinition @relation(fields: [permissionKey], references: [key])\n\n  @@id([templateId, permissionKey])\n  @@index([permissionKey])\n}\n\n// ===== ENTITLEMENTS =====\n\nmodel FeatureDefinition {\n  key           String           @id\n  origin        DefinitionOrigin @default(CODE)\n  kind          FeatureKind\n  module        String\n  meterKey      String?\n  unit          String?\n  name          String\n  description   String?\n  enforcement   Enforcement      @default(BLOCK)\n  upsellMessage String?\n  isActive      Boolean          @default(true)\n  createdAt     DateTime         @default(now())\n  updatedAt     DateTime         @updatedAt\n\n  planEntitlements PlanEntitlement[]\n  overrides        SchoolEntitlementOverride[]\n\n  @@index([module, isActive])\n  @@index([kind])\n  @@index([origin])\n}\n\nmodel PlanEntitlement {\n  planId     String\n  featureKey String\n  boolValue  Boolean?\n  limitValue Int?\n  enumValue  String?\n\n  plan    Plan              @relation(fields: [planId], references: [id], onDelete: Cascade)\n  feature FeatureDefinition @relation(fields: [featureKey], references: [key])\n\n  @@id([planId, featureKey])\n  @@index([featureKey])\n}\n\nmodel SchoolEntitlementOverride {\n  schoolId    String\n  featureKey  String\n  boolValue   Boolean?\n  limitValue  Int?\n  enumValue   String?\n  reason      String\n  expiresAt   DateTime?\n  createdById String\n  createdAt   DateTime  @default(now())\n\n  school  School            @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  feature FeatureDefinition @relation(fields: [featureKey], references: [key])\n\n  @@id([schoolId, featureKey])\n  @@index([featureKey])\n  @@index([expiresAt])\n  @@index([createdById])\n}\n\n// No entitlement row means the feature is not granted.\n// A null limitValue on a LIMIT feature represents an unlimited limit.\n// QUOTA features can use meterKey for usage tracking.\n\n// ===== PLATFORM SETTINGS DEFINITIONS =====\n\nmodel SettingDefinition {\n  key              String      @id\n  area             String\n  type             SettingType\n  constraints      Json?\n  dependsOn        Json?\n  requiresFeature  String?\n  isSecret         Boolean     @default(false)\n  group            String?\n  label            String\n  description      String?\n  defaultValue     Json\n  isSchoolEditable Boolean     @default(true)\n  sortOrder        Int         @default(0)\n  isActive         Boolean     @default(true)\n  createdAt        DateTime    @default(now())\n  updatedAt        DateTime    @updatedAt\n\n  @@index([area, isActive])\n  @@index([sortOrder])\n}\n\n// ===== AUTOMATION DEFINITIONS =====\n\nmodel AutomationRuleDefinition {\n  key              String                @id\n  module           String\n  trigger          AutomationTrigger\n  eventKey         String?\n  anchor           String?\n  paramsSchema     Json\n  allowedChannels  NotificationChannel[]\n  allowedAudiences String[]\n  templateKey      String\n  allowMultiple    Boolean               @default(false)\n  requiresFeature  String?\n  name             String\n  description      String?\n  defaultEnabled   Boolean               @default(false)\n  defaultParams    Json\n  defaultChannels  NotificationChannel[]\n  isActive         Boolean               @default(true)\n  createdAt        DateTime              @default(now())\n  updatedAt        DateTime              @updatedAt\n\n  @@index([module, isActive])\n  @@index([trigger])\n}\n\n// ===== MESSAGE TEMPLATES =====\n\nmodel MessageTemplate {\n  id                  String              @id @default(uuid())\n  key                 String\n  channel             NotificationChannel\n  locale              String              @default(\"en\")\n  category            TemplateCategory\n  variables           Json\n  isSchoolOverridable Boolean             @default(true)\n  subject             String?\n  body                String\n  isActive            Boolean             @default(true)\n  version             Int                 @default(1)\n  updatedById         String?\n  createdAt           DateTime            @default(now())\n  updatedAt           DateTime            @updatedAt\n\n  @@unique([key, channel, locale])\n  @@index([category, isActive])\n}\n\n// ===== AUDIT LOG =====\n\nmodel AuditLog {\n  id                String    @id @default(uuid())\n  userId            String?\n  schoolId          String?\n  actorMembershipId String?\n  actorName         String?\n  actorType         ActorType @default(user)\n  action            String\n  entity            String\n  entityId          String?\n  module            String?\n  requestId         String?\n  oldValue          Json?\n  newValue          Json?\n  ipAddress         String?\n  userAgent         String?\n  metadata          Json?\n  createdAt         DateTime  @default(now())\n\n  school School? @relation(fields: [schoolId], references: [id])\n\n  @@index([schoolId, createdAt])\n  @@index([entity, entityId])\n  @@index([userId, createdAt])\n  @@index([module, action])\n  @@index([requestId])\n  @@index([actorMembershipId])\n}\n\n// ===== PLATFORM NOTIFICATIONS =====\n\nmodel PlatformNotification {\n  id               String                   @id @default(uuid())\n  title            String\n  message          String\n  type             PlatformNotificationType\n  state            NotificationState        @default(QUEUED)\n  createdByAdminId String\n  metadata         Json?\n  sentAt           DateTime?\n  completedAt      DateTime?\n  createdAt        DateTime                 @default(now())\n  updatedAt        DateTime                 @updatedAt\n\n  recipients PlatformNotificationRecipient[]\n\n  @@index([state, createdAt])\n  @@index([type])\n}\n\nmodel PlatformNotificationRecipient {\n  id             String              @id @default(uuid())\n  notificationId String\n  schoolId       String\n  channel        NotificationChannel\n  status         DeliveryStatus      @default(PENDING)\n  retryCount     Int                 @default(0)\n  failedReason   String?\n  providerMsgId  String?\n  idempotencyKey String?             @unique\n  queuedAt       DateTime?\n  sentAt         DateTime?\n  failedAt       DateTime?\n  cancelledAt    DateTime?\n  nextRetryAt    DateTime?\n  readAt         DateTime?\n  deliveredAt    DateTime?\n  createdAt      DateTime            @default(now())\n  updatedAt      DateTime            @updatedAt\n\n  notification PlatformNotification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n  school       School               @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n\n  @@unique([notificationId, schoolId, channel])\n  @@index([schoolId, status])\n  @@index([status, nextRetryAt])\n}\n\n// ===== PLATFORM SETTINGS =====\n\nmodel PlatformSettings {\n  // Primary identifier\n  id String @id @default(uuid())\n\n  // Platform branding\n  platformName   String  @default(\"SchoolPortal\")\n  legalName      String?\n  shortName      String?\n  tagline        String?\n  logoUrl        String?\n  faviconUrl     String?\n  primaryColor   String?\n  secondaryColor String?\n\n  // Support and contact information\n  supportEmail    String  @default(\"support@schoolportal.com\")\n  supportPhone    String?\n  supportWhatsapp String?\n  companyAddress  String?\n\n  // Legal pages\n  termsUrl         String?\n  privacyPolicyUrl String?\n\n  // Email configuration\n  emailFromName    String?\n  emailFromAddress String?\n  emailReplyTo     String?\n\n  // SMS configuration\n  smsSenderId String?\n\n  // Website and support links\n  marketingSiteUrl String?\n  helpCenterUrl    String?\n  statusPageUrl    String?\n  socialLinks      Json?\n\n  // Default regional settings\n  defaultTimezone String @default(\"Africa/Lagos\")\n  defaultCountry  String @default(\"Nigeria\")\n  defaultCurrency String @default(\"NGN\")\n  defaultLocale   String @default(\"en-NG\")\n\n  // Subscription and reminder settings\n  subscriptionGracePeriodDays Int @default(7)\n  reminderDaysBeforeExpiry    Int @default(7)\n  termEndingReminderDays      Int @default(7)\n  defaultTrialDays            Int @default(0)\n\n  // Registration and school lifecycle settings\n  unconfirmedRegistrationHours  Int @default(72)\n  unverifiedSchoolTrialDays     Int @default(30)\n  unverifiedSchoolRetentionDays Int @default(60)\n\n  // Platform access and maintenance\n  allowNewRegistrations Boolean @default(true)\n  maintenanceMode       Boolean @default(false)\n  maintenanceMessage    String?\n  announcementBanner    String?\n\n  // Audit information\n  updatedById String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// ===== FEEDBACK =====\n\nmodel Feedback {\n  id        String         @id @default(uuid())\n  userId    String?\n  schoolId  String?\n  type      FeedbackType   @default(suggestion)\n  message   String\n  pageUrl   String?\n  status    FeedbackStatus @default(open)\n  response  String?\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  user   User?   @relation(fields: [userId], references: [id])\n  school School? @relation(fields: [schoolId], references: [id])\n\n  @@index([userId, createdAt])\n  @@index([schoolId, createdAt])\n  @@index([status])\n}\n"
}

